using Careersity.Application.Common.Exceptions;using Careersity.Application.CurriculumImports.Requests;using Careersity.Application.CurriculumImports.Services;using Careersity.Domain.Enums;using FluentAssertions;using Microsoft.Extensions.Logging.Abstractions;using Xunit;
namespace Careersity.UnitTests.Application;
public sealed class CurriculumImportServiceTests
{
 [Fact]public async Task ValidationWritesNothingAndValidImportIsAtomicCreateOnly(){await using var db=TestCatalogContext.Create();var service=new CurriculumImportService(db,NullLogger<CurriculumImportService>.Instance);var request=Valid();var validation=await service.ValidateAsync(request,default);validation.IsValid.Should().BeTrue();db.Careers.Should().BeEmpty();var result=await service.ImportAsync(request,default);result.Created.Courses.Should().Be(1);db.Careers.Should().ContainSingle();db.Courses.Should().ContainSingle();db.ExternalLearningResources.Should().ContainSingle();await FluentActions.Awaiting(()=>service.ImportAsync(request,default)).Should().ThrowAsync<ConflictException>();db.Careers.Should().ContainSingle();}
 [Fact]public async Task InvalidReferencesDuplicatesUrlsAndLimitsAreReported(){await using var db=TestCatalogContext.Create();var service=new CurriculumImportService(db,NullLogger<CurriculumImportService>.Instance);var r=Valid() with{Skills=[new("SQL","sql",SkillCategory.Technical),new("Duplicate","sql",SkillCategory.Tool)],Courses=[Valid().Courses.Single() with{Skills=[new("missing",SkillProficiencyLevel.Beginner,true)],ExternalResources=[new("missing","Bad",ExternalResourceType.Reading,ResourceAccessType.Free,"invalid",0,true)]}]};var result=await service.ValidateAsync(r,default);result.IsValid.Should().BeFalse();result.Errors.Select(x=>x.Code).Should().Contain(["DuplicateSlug","UnknownSkill","UnknownProvider","InvalidUrl"]);}
 private static CurriculumImportRequest Valid()=>new(new("Data","import-data","Description"),new("Analyst","import-analyst","Description",12),[new("SQL","import-sql",SkillCategory.Technical)],[new("Provider","import-provider","https://example.com")],[],[new("SQL Course","import-course",CourseDifficulty.Beginner,60,[new("import-sql",SkillProficiencyLevel.Beginner,true)],[new("Lesson","lesson",LessonContentType.Article,30,0,true)],[new("import-provider","Lecture",ExternalResourceType.LectureVideo,ResourceAccessType.Free,"https://example.com/lecture",0,true)])],new("Path","1.0",true,[new("Level",0,[new("import-course",0,true)])]));
}
